#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;
const int MAXN = 1000000;

long long fact[MAXN + 1], invfact[MAXN + 1];

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[n] = modpow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) invfact[i - 1] = invfact[i] * i % MOD;

    if (k == 1) {
        cout << (fact[n] - 1 + MOD) % MOD << '\n';
        return 0;
    }

    long long ans = 0;
    long long pow2 = 1;
    for (int i = 1; i <= n; ++i) {
        if (i > 1) pow2 = (pow2 * 2) % MOD;
        long long term = C(n - 1, i - 1) * pow2 % MOD;
        ans += term;
        if (ans >= MOD) ans -= MOD;
    }

    cout << ans << '\n';
    return 0;
}

