int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    if (!(cin >> n >> k)) return 0;

    if (k == 1) {
        // Only permutation [1..n] returns n; all others are bad
        long long fact = 1;
        for (int i = 2; i <= n; ++i) fact = fact * i % MOD;
        cout << (fact - 1 + MOD) % MOD << '\n';
        return 0;
    }

    int maxNK = max(n, k);
    vector<int> fact(maxNK + 1), invfact(maxNK + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxNK; ++i) fact[i] = mulmod(fact[i - 1], i);
    invfact[maxNK] = modpow(fact[maxNK], MOD - 2);
    for (int i = maxNK; i > 0; --i) invfact[i - 1] = mulmod(invfact[i], i);

    auto C = [&](int nn, int rr) -> int {
        if (rr < 0 || rr > nn) return 0;
        return mulmod(fact[nn], mulmod(invfact[rr], invfact[nn - rr]));
    };

    // dp[i] = number of permutations of length i with max at position i and
    // function returns i (i.e., last k elements contain i and no new max)
    // Recurrence:
    // dp[i] = sum_{t=1..min(k,i)} C(k-1, t-1) * dp[i-t]
    vector<int> dp(n + 1);
    dp[0] = 1; // empty prefix
    for (int i = 1; i <= n; ++i) {
        int limit = min(k, i);
        long long val = 0;
        for (int t = 1; t <= limit; ++t) {
            int comb = C(k - 1, t - 1);
            val += 1LL * comb * dp[i - t];
            if (val >= (long long)MOD * MOD) val %= MOD;
        }
        dp[i] = (int)(val % MOD);
    }

    // good permutations (function returns n)
    int good = mulmod(dp[n], fact[n - 1]);
    long long total = fact[n];
    int bad = submod((int)total, good);
    cout << bad << '\n';
    return 0;
}

