int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    // Precompute factorials and inverse factorials
    vector<int> fact(n + 1), invfact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = mulmod(fact[i - 1], i);
    invfact[n] = modpow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) invfact[i - 1] = mulmod(invfact[i], i);

    auto C = [&](int N, int R) -> int {
        if (R < 0 || R > N) return 0;
        return mulmod(fact[N], mulmod(invfact[R], invfact[N - R]));
    };

    // Precompute powers of 2 up to n
    vector<int> pow2(n + 1);
    pow2[0] = 1;
    for (int i = 1; i <= n; ++i) pow2[i] = addmod(pow2[i - 1], pow2[i - 1]);

    int ans = 0;
    int max_i = min(n, k);
    for (int i = 0; i <= max_i; ++i) {
        int comb = C(n - i, k - i);
        if (!comb) continue;
        int ways = mulmod(comb, pow2[n - k]);
        if (i & 1) ans = submod(ans, ways);
        else ans = addmod(ans, ways);
    }

    ans = mulmod(ans, fact[n]);
    cout << ans << '\n';
    return 0;
}

